profiles = [(1, 4, 8), (8, 16, 32), (32, 48, 64)]
def pick(n):
    for lo, opt, hi in profiles:
        if lo <= n <= hi: return (lo, opt, hi)
    return None
for n in [2, 20, 60, 100]:
    print("batch", n, "-> profile", pick(n))

